// shard key resolver
function shardKey(region, deviceId, shardsPerRegion){
  const key = region + '|' + deviceId;
  let h = 0; for (let i = 0; i < key.length; i++) { h = (h * 31 + key.charCodeAt(i)) >>> 0; }
  return h % shardsPerRegion;
}
```

